import {CFG,ITEMS,LAUNCHERS,ROUTES} from './data.js';
const copy=s=>structuredClone(s);export const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
export const item=id=>ITEMS.find(i=>i.id===id),route=s=>ROUTES.find(r=>r.id===s.route),launcher=s=>LAUNCHERS.find(l=>l.id===s.launcher);
export function fresh(players=1,seed=42,timer=60){return {version:12,phase:'story',scene:0,players:clamp(players,1,4),role:1,parts:[],route:'standard',launcher:'scout',grants:[],compared:[],day:0,log:[],flight:null,green:null,attempt:1,seed,rng:seed,timer,seals:[],friends:[],remaining:timer};}
export function log(s,text){s.log.push({day:s.day,text});}
export function seal(s,id){if(!s.seals.includes(id))s.seals.push(id);}
export function rng(s){s.rng=(s.rng*9301+49297)%233280;return s.rng/233280;}
export function stats(s){const p=s.parts.map(item),l=launcher(s);const cost=p.reduce((a,i)=>a+i.cost,l.cost),kg=p.reduce((a,i)=>a+i.kg,0),power=p.reduce((a,i)=>a+i.gen,l.power);return {cost,kg,power,use:p.reduce((a,i)=>a+i.w,l.overhead)+(s.flight?.extraW||0),arrival:power*CFG.solarArrival,dv:l.dv-kg*CFG.dvPerKg,budget:CFG.budget+s.grants.reduce((a,i)=>a+CFG.grants[i],0)-cost};}
export function errors(s){const t=stats(s),l=launcher(s),r=route(s),e=[];if(!s.parts.some(k=>item(k).kind==='chamber'))e.push('Install a biological chamber.');if(!s.parts.some(k=>['antenna','backup'].includes(k)))e.push('Install an antenna or backup link so the mission can return observations.');if(t.kg>l.cap)e.push(`Payload ${t.kg.toFixed(1)} kg exceeds ${l.cap} kg. Remove equipment or choose a larger launcher.`);if(t.use>t.arrival)e.push(`Arrival supply ${t.arrival.toFixed(0)} W is below consumption ${t.use} W. Add panels, choose a stronger bus or remove equipment.`);if(t.dv<r.dv)e.push(`Available delta-v ${t.dv.toFixed(2)} is below ${r.dv} km/s. Reduce mass or choose another launcher/route.`);if(t.budget<0)e.push('Design exceeds available funding.');return e;}
export function toggle(s0,id){const p=item(id);if(s0.phase!=='lab'||!p||(s0.players>1&&p.role!==s0.role))return s0;const s=copy(s0);if(s.parts.includes(id))s.parts=s.parts.filter(k=>k!==id);else {if(p.kind==='chamber')s.parts=s.parts.filter(k=>item(k).kind!=='chamber');s.parts.push(id);}return stats(s).budget<0?s0:s;}
export function chooseLauncher(s0,id){if((s0.players>1&&s0.role!==3)||s0.phase!=='lab'||!LAUNCHERS.some(l=>l.id===id))return s0;const s=copy(s0);s.launcher=id;return stats(s).budget<0?s0:s;}
export function selectRoute(s0,id){if((s0.players>1&&s0.role!==3)||s0.phase!=='lab'||!ROUTES.some(r=>r.id===id))return s0;const s=copy(s0);s.route=id;if(!s.compared.includes(id))s.compared.push(id);return s;}
export function claim(s0,i){if((s0.players>1&&s0.role!==3)||s0.phase!=='lab'||![0,1].includes(i)||s0.grants.includes(i))return s0;const s=copy(s0),t=stats(s);const ok=i===0?s.parts.some(k=>item(k).kind==='chamber')&&t.use<=t.power&&t.kg<=launcher(s).cap:s.grants.includes(0)&&s.compared.length>=2;if(!ok)return s0;s.grants.push(i);seal(s,i?'routes':'design');log(s,`Design review ${i+1}: +${CFG.grants[i]} credits.`);return s;}
export const milestone=s=>errors(s).length===0&&s.grants.length===2?4:s.grants.includes(1)?3:s.grants.includes(0)?2:1;
export function launch(s0){if((s0.players>1&&s0.role!==3)||s0.phase!=='lab'||errors(s0).length||s0.grants.length!==2)return s0;const s=copy(s0);s.phase='voyage';s.day=0;s.rng=s.seed;const d=route(s).days;const events=[...(s.parts.includes('chamberA')?[{type:'thermal',day:Math.round(d*.5)}]:[{type:'auto',day:Math.round(d*.5)}]),{type:'comms',day:Math.round(d*(.45+rng(s)*.2))},{type:'mechanical',day:Math.round(d*(.2+rng(s)*.6))}].sort((a,b)=>a.day-b.day);s.flight={charge:CFG.batteryWh,temp:CFG.baseTemp,humidity:70,risk:0,stored:0,sent:0,lost:0,generated:0,energy:0,outages:0,pending:null,events,index:0,integrity:100,damageRate:0,repairs:s.parts.includes('toolkit')?2:0,extraW:0,delayDays:0,lowTelemetry:false,heat:0,decisions:[],lastGen:stats(s).power};seal(s,'launch');log(s,`Launched with ${stats(s).kg.toFixed(1)} kg. Scenario seed ${s.seed}.`);return s;}
export const duration=s=>route(s).days+(s.flight?.delayDays||0);
export const delay=s=>4+20*Math.min(1,s.day/route(s).days);
function finish(s){const f=s.flight;if(f.outages>=2||f.risk>=80||f.integrity<=0||s.day>=duration(s)){s.phase='report';if(s.day>=duration(s)&&f.integrity>0&&f.risk<80&&f.outages<2)seal(s,'arrival');}}
function events(s){const f=s.flight;while(f.index<f.events.length&&f.events[f.index].day<=s.day&&!f.pending){const event=f.events[f.index++];if(event.type==='auto'){f.risk+=1;log(s,'Vanguard controller held the climate through a heat anomaly.');}else if(event.type==='thermal'&&s.parts.includes('thermal')){f.extraW+=10;f.risk+=3;seal(s,'repair');log(s,'Thermal controller responded automatically: +10 W ongoing load, +3 risk.');}else if(event.type==='comms'&&s.parts.includes('backup')){const lost=f.stored*.1;f.stored-=lost;f.lost+=lost;log(s,'Backup link restored contact. 10% of onboard buffered data lost; data already received on Earth is safe.');seal(s,'repair');}else{f.pending=event.type;s.remaining=s.timer;log(s,`${event.type} incident: onboard response required.`);}}if(!f.pending)finish(s);}
export function advance(s0){if(s0.phase!=='voyage'||s0.flight.pending)return s0;const s=copy(s0),f=s.flight,t=stats(s);const next=f.events[f.index]?.day??Infinity;const days=Math.min(30,duration(s)-s.day,Math.max(0,next-s.day));if(days<=0){events(s);return s;}s.day+=days;const ratio=Math.min(1,s.day/route(s).days),gen=t.power*(1-(1-CFG.solarArrival)*ratio);const hours=days*24;f.lastGen=gen;f.energy+=t.use*hours;const raw=f.charge+(gen-t.use)*hours;f.charge=clamp(raw,0,CFG.batteryWh);const out=raw<0;f.outages=out?f.outages+1:0;const active=s.parts.includes('chamberB'),sensor=s.parts.includes('thermal'),drift=active?.05:sensor?.16:.4;
f.temp=2.5+(f.temp-2.5)*(active?.18:.65)+drift+(out?5:0)+f.heat;f.humidity=clamp(70+(f.humidity-70)*.65-drift*2-(out?10:0)-f.heat*2);f.risk=clamp(f.risk+(Math.max(0,f.temp-4)*5+Math.max(0,60-f.humidity)*.5+(active?0:1.5))*days/30);f.integrity=clamp(f.integrity-(out?30:0)-f.damageRate*days/30);
const produced=(24+(s.parts.includes('dosimeter')?8:0))*(f.lowTelemetry?.5:1)*days/30;f.generated+=produced;const available=f.stored+produced,link=s.parts.includes('antenna')?64:16,sent=out?0:Math.min(available,link*days/30);f.sent+=sent;f.lost+=Math.max(0,available-sent-CFG.storageMB);f.stored=Math.min(CFG.storageMB,available-sent);if(f.sent>0)seal(s,'data');log(s,`${days} days · ${gen.toFixed(0)} / ${t.use} W · ${f.charge.toFixed(0)} Wh reserve · risk ${f.risk.toFixed(1)} · +${sent.toFixed(1)} MB received.`);if(f.outages>=2||f.risk>=80||f.integrity<=0){finish(s);return s;}events(s);return s;}
export function options(s){const f=s.flight;if(!f?.pending)return [];if(f.pending==='thermal')return [{id:'repair',name:'Repair the cooling loop',desc:'Use 1 repair. +3 risk.',disabled:f.repairs<1},{id:'battery',name:'Emergency cooling pulse',desc:'Use 600 Wh. +12 risk.',disabled:f.charge<600},{id:'wait',name:'Wait and observe',desc:'+6 °C, −12% humidity, +35 risk; persistent heat leak.',disabled:false}];if(f.pending==='comms')return [{id:'align',name:'Realign autonomously',desc:'Add 12 days to the voyage; keep full observations.',disabled:false},{id:'essential',name:'Prioritize essential telemetry',desc:'Discard buffered data and halve future observations. No delay.',disabled:false}];return [{id:'repair',name:'Repair the damaged assembly',desc:'Use 1 repair. Stop ongoing damage.',disabled:f.repairs<1},{id:'power',name:'Isolate with battery power',desc:'Use 500 Wh and lose 20 integrity. Stop ongoing damage.',disabled:f.charge<500},{id:'continue',name:'Continue without repair',desc:'Lose 15 integrity now and 10 per 30 days.',disabled:false}];}
export function resolve(s0,id){const o=options(s0).find(o=>o.id===id&&!o.disabled);if(!o)return s0;const s=copy(s0),f=s.flight,type=f.pending;if(type==='thermal'){if(id==='repair'){f.repairs--;f.risk+=3;}if(id==='battery'){f.charge-=600;f.energy+=600;f.risk+=12;}if(id==='wait'){f.temp+=6;f.humidity-=12;f.risk+=35;f.heat+=1;}}else if(type==='comms'){if(id==='align')f.delayDays+=12;else{f.lost+=f.stored;f.stored=0;f.lowTelemetry=true;}}else{if(id==='repair'){f.repairs--;f.damageRate=0;}if(id==='power'){f.charge-=500;f.energy+=500;f.integrity-=20;f.damageRate=0;}if(id==='continue'){f.integrity-=15;f.damageRate=10;}}f.risk=clamp(f.risk);f.humidity=clamp(f.humidity);f.decisions.push({day:s.day,type,id});f.pending=null;seal(s,'repair');log(s,`${type}: ${o.name}. ${o.desc}`);finish(s);if(s.phase==='voyage')events(s);return s;}
export function tick(s0,seconds,paused=false){if(paused||s0.phase!=='voyage'||!s0.flight.pending||!s0.timer)return s0;const s=copy(s0);s.remaining=Math.max(0,s.remaining-Math.max(0,seconds));if(s.remaining)return s;const preference=s.flight.pending==='comms'?['essential']:['repair','battery','power','wait','continue'];const chosen=preference.find(id=>options(s).some(o=>o.id===id&&!o.disabled));log(s,`Response time elapsed: onboard fallback selected ${chosen}.`);return resolve(s,chosen);}
export function report(s){const f=s.flight,arrived=s.day>=duration(s)&&f.outages<2&&f.integrity>0&&f.risk<80,kind=!arrived?'failure':f.risk>35||f.sent<100||f.lost>64||f.integrity<50?'partial':'success';return {arrived,kind,score:Math.max(0,Math.round((arrived?100:0)+100-f.risk+f.sent/4-f.lost/4)),reason:f.outages>=2?'Energy supply fell below demand. Increase arrival generation.':f.risk>=80?'Heat exposure exceeded the model threshold. Add thermal control or respond earlier.':f.integrity<50?'Mechanical damage accumulated. Reserve a repair or battery energy.':f.sent<100||f.lost>64?'The science link was the bottleneck. Compare high-gain throughput against mass and power.':f.risk>35?'The chamber arrived with elevated risk. Improve thermal redundancy.':'Power, thermal protection and communications remained balanced.'};}
export function startGreen(s0){if(s0.phase!=='report'||!report(s0).arrived)return s0;const s=copy(s0);s.phase='greenhouse';s.green={step:0,cells:2+(s.flight.charge>=800?1:0)+(s.flight.integrity>=80?1:0),colony:100-s.flight.risk,lights:false,data:0,choices:[]};return s;}
export function greenChoice(s0,id){if(s0.phase!=='greenhouse'||!['care','rush'].includes(id)||s0.green.step>=4)return s0;const s=copy(s0),g=s.green;if(id==='care'&&g.step<3&&g.cells<1)return s0;if(id==='care'&&g.step<3)g.cells--;const gains=[[15,-15],[15,-20],[10,-10],[0,0]];g.colony=clamp(g.colony+gains[g.step][id==='care'?0:1]);if(g.step===2)g.lights=id==='care';if(g.step===3)g.data=id==='care'?50:10;g.choices.push(id);g.step++;if(g.step===4){seal(s,'garden');s.phase='epilogue';seal(s,'paper');}log(s,`Hypothetical greenhouse step ${g.step}: ${id}.`);return s;}
export function redesign(s0){const s=copy(s0);s.phase='lab';s.flight=null;s.green=null;s.day=0;s.attempt++;s.scene=0;log(s,'Redesign: equipment and funding retained. Same seed allows fair comparison.');return s;}
export function validSave(s){try{return !!s&&s.version===12&&['story','friends','lab','voyage','report','greenhouse','epilogue'].includes(s.phase)&&Number.isInteger(s.players)&&s.players>=1&&s.players<=4&&Number.isInteger(s.role)&&s.role>=0&&s.role<4&&Array.isArray(s.parts)&&s.parts.every(id=>item(id))&&new Set(s.parts).size===s.parts.length&&s.parts.filter(id=>item(id).kind==='chamber').length<=1&&route(s)&&launcher(s)&&Array.isArray(s.grants)&&s.grants.every(i=>i===0||i===1)&&new Set(s.grants).size===s.grants.length&&Array.isArray(s.compared)&&s.compared.every(id=>ROUTES.some(r=>r.id===id))&&['seals','friends','log'].every(k=>Array.isArray(s[k]))&&[0,60,120].includes(s.timer)&&Number.isFinite(s.remaining)&&Number.isFinite(s.seed)&&Number.isFinite(s.day)&&s.day>=0&&stats(s).budget>=0&&(!['voyage','report','greenhouse','epilogue'].includes(s.phase)||(s.flight&&['charge','temp','humidity','risk','stored','sent','lost','generated','energy','integrity','index','delayDays','repairs','extraW'].every(k=>Number.isFinite(s.flight[k]))&&[null,'thermal','comms','mechanical'].includes(s.flight.pending)&&Array.isArray(s.flight.events)&&Array.isArray(s.flight.decisions)))&&(!['greenhouse','epilogue'].includes(s.phase)||(s.green&&Number.isInteger(s.green.step)&&s.green.step>=0&&s.green.step<=4&&Number.isFinite(s.green.colony)&&Number.isFinite(s.green.cells)));}catch{return false;}}
